const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.book}"/></svg>`;
let employees=[],user,profile,posts=[],requests=[],notifications=[],votes=[],progress=[],people=[],page='home',adminKind='news',slide=0,carouselPaused=false,editId=null,results={},month=new Date(),installPrompt,loading=false,toastTimer,authEpoch=0,entryStep=0,entryMode='auto',booting=true,initialResolved=false;
const onboardingSlides=[
  {tag:'Nossa gente',title:'Tudo que conecta você ao Cana Brava.',body:'Receba comunicados, acompanhe novidades e acesse os serviços internos em um só lugar.',image:'/onboarding/slide-01.jpg'},
  {tag:'Seu dia a dia',title:'Ônibus, cursos, eventos e muito mais.',body:'Veja horários e pontos de embarque, treinamentos, aniversariantes, vagas e informações importantes.',image:'/onboarding/slide-02.jpg'},
  {tag:'Mais praticidade',title:'Um portal simples, bonito e feito para os Braveiros.',body:'Entre com sua matrícula, acompanhe o que importa e resolva tudo com poucos toques.',image:'/onboarding/slide-03.jpg'}
];
const staff=()=>['admin','super_admin'].includes(profile?.role);const manager=()=>staff()||profile?.role==='ombudsman';
const labels=Object.fromEntries(modules.map(m=>[m[0],m[1]]));const publicPosts=k=>posts.filter(p=>p.kind===k&&p.published);const notices=()=>posts.filter(p=>activeNotice(p));
const btn=(txt,act,cls='secondary')=>`<button type="button" class="${cls}" data-action="${esc(act)}" aria-label="${esc(({theme:'Alternar tema','nav:notifications':'Notificações','nav:profile':'Meu perfil',prev:'Anterior',next:'Próximo',pause:'Pausar ou retomar carrossel'}[act]|| (act.startsWith('social-comments:')?'Ver comentários':act.startsWith('social-share:')?'Compartilhar publicação':act.startsWith('social-like:')?'Curtir publicação':txt.replace(/<[^>]*>/g,''))))}">${txt}</button>`;
function toast(msg){let t=document.querySelector('#toast');if(!t){t=document.createElement('div');t.id='toast';t.setAttribute('role','status');document.body.append(t)}t.textContent=msg;t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,4500)}
function check(r){if(r.error)throw new Error(r.error.message);return r.data}
const dateLabel=s=>s?new Date(s.length===10?s+'T12:00:00':s).toLocaleDateString('pt-BR',{timeZone:'America/Bahia'}):'';
function link(s,label){const url=safeUrl(s);return url?`<a class="secondary link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ${icon('external')}</a>`:''}
function input(name,label,type='text',value='',required=false){return `<label>${esc(label)}${type==='textarea'?`<textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}>`}</label>`}
function brand(){return `<span class="brand"><img src="/icon.svg" alt=""><span>braveiros<span class="dot">.</span><small>CANA BRAVA RESORT</small></span></span>`}
function splashScreen(){app.innerHTML=`<div class="splash-screen"><div class="splash-card">${brand()}<div class="loading-dots" role="status" aria-label="Carregando"><span></span><span></span><span></span></div></div></div>`}
function onboardingScreen(){const t=onboardingSlides[entryStep],last=entryStep===onboardingSlides.length-1;app.innerHTML=`<div class="onboarding-shell"><section class="onboarding-stage" style="--slide-image:url('${esc(t.image)}')"><div class="onboarding-overlay"></div><div class="onboarding-top">${btn('Já tenho conta','onboarding-login','text-button light')}</div><div class="onboarding-body"><div class="onboarding-copy"><p class="eyebrow light">${esc(t.tag)}</p><h1>${esc(t.title)}</h1><p>${esc(t.body)}</p></div><div class="onboarding-bottom"><div class="auth-dots">${onboardingSlides.map((_,i)=>`<button type="button" class="auth-dot ${i===entryStep?'active':''}" data-action="onboarding-slide:${i}" aria-label="Slide ${i+1}"></button>`).join('')}</div><div class="onboarding-actions">${entryStep?btn('Voltar','onboarding-prev','secondary soft'):''}${btn(last?'Vamos começar':'Próximo',last?'onboarding-finish':'onboarding-next','primary')}</div></div></div></section></div>`;window.scrollTo(0,0)}
function authScreen(signup=false){entryMode=signup?'signup':'login';app.innerHTML=`<div class="login-shell br-login-shell"><div class="br-login-feature"><div class="br-login-feature-top">${brand()}<span>CONEXÃO QUE TRANSFORMA</span></div><div class="br-login-feature-content"><span class="br-login-sun">✳</span><span class="br-login-overline">FEITO PARA A NOSSA GENTE</span><h2>Todo dia é uma nova história para compartilhar.</h2><p>Notícias, conexões, oportunidades e serviços. Tudo em um só lugar, do nosso jeito.</p></div><div class="br-login-feature-bottom">CANA BRAVA RESORT <span>•</span> NOSSO PORTAL</div></div><div class="login-wrap br-login-wrap"><div class="login-head">${brand()}</div><div class="login-copy"><h1>${signup?'Crie sua conta':'Que bom ter você aqui.'}</h1><p class="muted">${signup?'Seu acesso será liberado pela administração.':'Entre com sua matrícula e senha.'}</p></div>${db?`<form id="auth-form" data-signup="${signup}">${signup?input('name','Nome completo','text','',true)+input('department','Departamento','text','',true)+input('matricula','Número da matrícula','text','',true)+input('contact_email','E-mail de contato (opcional)','email'):input('login','Matrícula (ou e-mail de conta antiga)','text','',true)}<label>Senha<input name="password" type="password" minlength="8" maxlength="128" required autocomplete="${signup?'new-password':'current-password'}"></label><button class="primary">${signup?'Criar conta':'Entrar no portal'}</button></form><div class="auth-links">${btn(signup?'Já tenho conta':'Criar minha conta',signup?'login':'signup','text-button')}${signup?'':btn('Esqueci minha senha','reset','text-button')}</div>`:'<div class="empty">Configure as variáveis Supabase para começar.</div>'}</div></div>`;window.scrollTo(0,0)}
function guestScreen() {
  if (booting) return splashScreen();
  if (entryMode === 'signup') return authScreen(true);
  if (entryMode === 'login' || readLocal('braveiros_onboarding_seen') === 'true') return authScreen(false);
  entryMode = 'onboarding';
  return onboardingScreen();
}
function startupError(error) {
  booting=false;
  console.error('Braveiros '+VERSION, error);
  app.innerHTML=`<div class="center"><div class="card card-body">${brand()}<h2>Não foi possível carregar</h2><p>Confira sua conexão e tente novamente.</p><p class="body-text">${esc(error?.message||'Falha de inicialização')}</p>${btn('Tentar novamente','retry-start','primary')}${user?btn('Sair','logout'):''}<small>Versão ${VERSION}</small></div></div>`;
}

async function load(){
  if(!user)return;
  const epoch=authEpoch, uid=user.id;
  const p=check(await db.from('profiles').select('*').eq('id',uid).maybeSingle());
  if(epoch!==authEpoch)return;
  profile=p;
  if(!p?.active||p.must_change_password){render();return;}
  const role=check(await db.rpc('br_role'));
  if(epoch!==authEpoch)return;
  if(!role){profile={...p,active:false};render();return;}
  const fetches=await Promise.all([
    db.from('posts').select('*').order('created_at',{ascending:false}).limit(500),
    db.from('requests').select('*').order('created_at',{ascending:false}).limit(500),
    db.from('notifications').select('*').order('created_at',{ascending:false}).limit(100),
    db.from('votes').select('*'),db.from('progress').select('*'),
    staff()?db.from('profiles').select('*').order('name').limit(1000):Promise.resolve({data:[]})
  ]);
  if(epoch!==authEpoch)return;
  [posts,requests,notifications,votes,progress,people]=fetches.map(check);
  employees=[]; rosterError='';

  if(epoch===authEpoch){await Promise.all([loadSocial(epoch),loadPeople(epoch)]);if(epoch===authEpoch)render();}
}
let rosterError='';
function navItem(k,title,i){return `<button class="nav ${page===k?'selected':''}" data-action="nav:${k}">${icon(i)}<span>${esc(title)}</span></button>`}
function banner(){let list=notices();if(!list.length)return '';slide%=list.length;const p=list[slide];return `<section class="banner" aria-label="Comunicados" id="carousel"><div class="banner-content"><div class="eyebrow">${icon('megaphone')} COMUNICADO INTERNO <span>${slide+1}/${list.length}</span></div><h2>${esc(p.title)}</h2><p>${esc(p.body)}</p>${btn('Ver comunicados →','nav:notice','banner-link')}</div>${list.length>1?`<div class="carousel-controls">${btn('‹','prev','round')}${list.map((_,i)=>btn(i===slide?'●':'○','slide:'+i,'dot-button')).join('')}${btn('›','next','round')}${btn(carouselPaused?'▶':'Ⅱ','pause','round')}</div>`:''}</section>`}
function heading(title,sub){return `<div class="page-heading"><div><div class="eyebrow">SEU PORTAL</div><h1>${esc(title)}</h1><p class="muted">${esc(sub)}</p></div></div>`}
function gridModules(){return `<div class="quick-grid">${modules.filter(m=>m[0]!=='news'&&m[0]!=='notice').map(m=>`<button class="quick" data-action="nav:${m[0]}"><span class="quick-icon">${icon(m[2])}</span><strong>${esc(m[1])}</strong><small>${esc(m[3])}</small><span class="arrow">↗</span></button>`).join('')}</div>`}
function legacyHome(){return `${heading('Olá, '+(profile.name.split(' ')[0]||'Braveiro')+'!','Seu dia a dia mais conectado.')}<section class="intro"><div><span class="eyebrow">CONEXÃO QUE TRANSFORMA</span><h2>É bom fazer parte.</h2><p>Informações, oportunidades e serviços, tudo em um só lugar.</p>${btn('Explore os serviços →','nav:services','primary')}</div><div class="sun-art" aria-hidden="true"><i></i><i></i><i></i></div></section><div class="section-head"><h2>Acesso rápido</h2></div>${gridModules()}<div class="section-head"><h2>Acontece no Cana</h2>${btn('Ver notícias →','nav:news','text-button')}</div><div class="cards">${publicPosts('news').slice(0,3).map(postCard).join('')||empty('Nenhuma notícia publicada ainda.')}</div>`}
function empty(msg){return `<div class="empty">${icon('book')}<p>${esc(msg)}</p></div>`}
function postCard(p){let e=p.extra||{},m=modules.find(m=>m[0]===p.kind);let extra=(fields[p.kind]||[]).filter(f=>!['url','image','choices'].includes(f[0])).map(([k,l])=>e[k]?`<div class="meta"><span>${esc(l)}</span><strong>${esc(e[k])}</strong></div>`:'').join('');let action=link(e.url,p.kind==='courses'?'Acessar treinamento':p.kind==='jobs'?'Ver candidatura':'Acessar material');if(p.kind==='courses')action+=btn(progress.some(x=>x.post_id===p.id&&x.completed)?'✓ Concluído':'Marcar como concluído','course:'+p.id);if(p.kind==='polls'){const voted=votes.find(v=>v.post_id===p.id);action=voted?`<p class="pill">Voto registrado</p>`:(Array.isArray(e.choices)?e.choices:[]).map((c,i)=>btn(esc(c),'vote:'+p.id+':'+i)).join('');if(staff())action+=btn('Ver resultados','results:'+p.id)+(results[p.id]||[]).map(r=>`<p>${esc(r.choice)}: ${esc(r.total)}</p>`).join('')}
return `<article class="card">${safeUrl(e.image)?`<img class="cover" src="${esc(safeUrl(e.image))}" loading="lazy" alt="" referrerpolicy="no-referrer">`:''}<div class="card-body"><div class="eyebrow">${icon(m?.[2]||'book')} ${esc(m?.[1]||'')} · ${dateLabel(p.created_at)}</div><h3>${esc(p.title)}</h3><p class="body-text">${esc(p.body)}</p>${extra}<div class="actions">${action}</div></div></article>`}
function calendar(){const y=month.getFullYear(),m=month.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate(),items=publicPosts('events');return `<div class="card calendar"><div class="section-head">${btn('‹','month:-1')}<h2>${month.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</h2>${btn('›','month:1')}</div><div class="calendar-grid">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(d=>`<div class="weekday">${d}</div>`).join('')}${Array.from({length:first},()=>'<div></div>').join('')}${Array.from({length:days},(_,i)=>{const day=`${y}-${String(m+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return `<div class="day"><strong>${i+1}</strong>${items.filter(p=>p.extra?.date===day).map(p=>`<span>${esc(p.title)}</span>`).join('')}</div>`}).join('')}</div></div>`}
function requestView(kind){return `${heading(labels[kind],kind==='ombudsman'?'Canal confidencial identificado. Somente você e a equipe de Ouvidoria podem consultar sua manifestação pelo aplicativo.':'Envie e acompanhe suas solicitações.')}<form id="request-form" class="card form-card" data-kind="${kind}">${input('title','Assunto','text','',true)}${input('body','Descreva sua solicitação','textarea','',true)}<button class="primary">Enviar ${kind==='suggestions'?'sugestão':'solicitação'}</button></form><h2>Minhas solicitações</h2><div class="cards">${requests.filter(r=>r.owner===user.id&&r.kind===kind).map(r=>requestCard(r,false)).join('')||empty('Nenhuma solicitação registrada.')}</div>`}
function requestCard(r,manage){return `<article class="card card-body"><div class="eyebrow">${dateLabel(r.created_at)} · ${esc(labels[r.kind])}</div><h3>${esc(r.title)}</h3><span class="pill">${esc(r.status)}</span><p class="body-text">${esc(r.body)}</p>${r.response?`<div class="response"><strong>Resposta</strong><p>${esc(r.response)}</p></div>`:''}${manage?`<form class="reply-form" data-id="${r.id}"><label>Status<select name="status">${['Recebido','Em análise','Respondido','Encerrado'].map(s=>`<option ${s===r.status?'selected':''}>${s}</option>`).join('')}</select></label>${input('response','Resposta','textarea',r.response)}<button class="primary">Salvar atendimento</button></form>`:''}</article>`}
async function identityRequest(body,authenticated=true){const headers={'Content-Type':'application/json'};if(authenticated){const {data:{session}}=await db.auth.getSession();if(!session)throw Error('Entre novamente.');headers.Authorization='Bearer '+session.access_token;}const r=await fetch('/api/identity',{method:'POST',headers,body:JSON.stringify(body)});const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Operação não autorizada.');return data;}
function registrationPanel(){
 if(!staff())return '';
 const pending=people.filter(p=>p.role==='employee'&&!p.active&&p.registration_status==='pending');
 const history=people.filter(p=>p.registration_reviewed_at).sort((a,b)=>String(b.registration_reviewed_at).localeCompare(String(a.registration_reviewed_at)));
 return `<section class="card card-body"><div class="section-head"><h2>Solicitações de cadastro</h2><span class="pill">${pending.length} pendentes</span>${btn('Atualizar','refresh')}</div>${pending.map(p=>`<div class="admin-row"><div><strong>${esc(p.name)}</strong><small>Matrícula: ${esc(p.matricula)} · ${esc(p.department)}</small></div><div class="actions">${btn('Aprovar','registration-review:'+p.id+':approve','primary')}${btn('Recusar','registration-review:'+p.id+':reject','danger')}</div></div>`).join('')||empty('Nenhuma solicitação pendente.') }<details><summary>Histórico de decisões</summary>${history.map(p=>`<div class="admin-row"><div><strong>${esc(p.name)}</strong><small>${esc(p.matricula)} · ${p.registration_status==='approved'?'Aprovado':'Recusado'} · ${dateLabel(p.registration_reviewed_at)} · ${esc(people.find(x=>x.id===p.registration_reviewed_by)?.name||'Administração')}</small></div></div>`).join('')||empty('Nenhuma decisão registrada.')}</details></section>`;
}
function admin(){if(!manager())return empty('Acesso restrito.');if(!staff())return `${heading('Ouvidoria | Atendimento','Manifestações de acesso restrito.')}<div class="cards">${requests.filter(r=>r.kind==='ombudsman').map(r=>requestCard(r,true)).join('')||empty('Nenhuma manifestação.')}</div>`;const p=posts.find(p=>p.id===editId);return `${heading('Central de gestão','Publicações, acessos e solicitações organizados em um só lugar.')}${registrationPanel()}<div class="br-management-links">${btn('＋ Nova publicação','social-new','primary')}${profile.role==='super_admin'?btn('Gerenciar pessoas','nav:people','secondary'):''}${btn('Atualizar painel','refresh','secondary')}</div><div class="stats"><div><small>Conteúdos</small><strong>${posts.length}</strong></div><div><small>Solicitações visíveis</small><strong>${requests.filter(r=>r.kind!=='ombudsman').length}</strong></div><div><small>Colaboradores ativos</small><strong>${people.filter(p=>p.active).length}</strong></div></div><div class="admin-grid"><section class="card form-card"><h2>${p?'Editar conteúdo':'Novo conteúdo'}</h2><label>Módulo<select id="admin-kind">${publicKinds.map(k=>`<option value="${k}" ${k===adminKind?'selected':''}>${esc(labels[k])}</option>`).join('')}</select></label><form id="post-form">${input('title','Título','text',p?.title,true)}${input('body','Descrição','textarea',p?.body)}${(fields[adminKind]||[]).map(([k,l,t])=>input(k,l,t||'text',Array.isArray(p?.extra?.[k])?p.extra[k].join('\n'):p?.extra?.[k])).join('')}<label class="check"><input type="checkbox" name="published" ${p?.published??true?'checked':''}> Publicar conteúdo</label><div class="actions"><button class="primary">${p?'Salvar alterações':'Salvar conteúdo'}</button>${p?btn('Cancelar','cancel-edit'):''}</div></form></section><section class="card card-body"><h2>Conteúdos · ${esc(labels[adminKind])}</h2>${posts.filter(p=>p.kind===adminKind).map(p=>`<div class="admin-row"><div><strong>${esc(p.title)}</strong><small>${p.published?'Publicado':p.scheduled_at?'Agendado: '+new Date(p.scheduled_at).toLocaleString('pt-BR',{timeZone:'America/Bahia'}):'Rascunho'}</small></div><div>${btn('Editar',['news','notice'].includes(p.kind)?'social-edit:'+p.id:'edit:'+p.id)} ${btn('Excluir','delete:'+p.id,'danger')}</div></div>`).join('')||empty('Nenhum conteúdo cadastrado.')}</section></div><h2>Atendimentos SAC e sugestões</h2><div class="cards">${requests.filter(r=>r.kind!=='ombudsman').map(r=>requestCard(r,true)).join('')||empty('Nenhum atendimento.')}</div>${profile.role==='super_admin'?`<section class="br-admin-shortcut card"><div><span class="eyebrow">ACESSO EXCLUSIVO</span><h2>Equipe, cargos e departamentos</h2><p>Gerencie permissões e dados profissionais em um único lugar, com registro das alterações.</p></div>${btn('Abrir gestão de pessoas','nav:people','primary')}</section>`:''}`}
function content(){if(page==='home')return socialFeed();if(page==='composer')return socialComposer();if(page==='people')return peoplePanel();if(page==='services')return heading('Serviços','Tudo o que você precisa.')+gridModules()+(manager()?btn('Administração','nav:admin'):'' )+(profile.role==='super_admin'?btn('Pessoas e departamentos','nav:people'):'' );if(page==='admin')return admin();if(page==='notifications')return heading('Avisos','Suas notificações')+btn('Marcar todas como lidas','read-all')+`<div class="card card-body">${notifications.map(n=>`<button class="notification ${n.read?'':'unread'}" data-action="notification:${n.id}">${icon('bell')}<span><strong>${esc(n.title)}</strong><small>${dateLabel(n.created_at)}</small></span>${n.read?'':'<i></i>'}</button>`).join('')||empty('Nenhuma notificação.')}</div>`;if(page==='profile')return heading('Meu perfil','Preferências do aplicativo')+`<div class="card card-body">${avatar(profile.avatar_path,profile.name)}<h2>${esc(profile.name)}</h2><p>${esc(profile.job_title||'')}</p><p>${progress.filter(x=>x.completed).length} cursos concluídos</p><form id="avatar-form"><label>Foto de perfil<input name="avatar" type="file" accept="image/jpeg,image/png,image/webp" required></label><button class="secondary">Atualizar foto</button></form>${manager()?btn('Administração','nav:admin'):''}${profile.role==='super_admin'?btn('Pessoas e departamentos','nav:people'):''}<p>${esc(profile.department)}</p><p>Matrícula: ${esc(profile.matricula||"Não vinculada")}</p><p>${esc(profile.contact_email||"")}</p><div class="actions">${btn('Ativar notificações','push-on','primary')}${btn('Desativar neste dispositivo','push-off')}${btn('Instalar aplicativo','install')}${btn('Alternar tema','theme')}${btn('Sair','logout','danger')}</div></div>`;if(['sac','suggestions','ombudsman'].includes(page))return requestView(page);if(page==='bravadesk')return heading('BravaDesk','Central de demandas de Marketing')+`<div class="card card-body"><h2>Acesse a central de serviços</h2><p>O BravaDesk é um sistema independente. Use seu login habitual.</p>${link(env.VITE_BRAVADESK_URL||'https://mktdesk.vercel.app','Abrir BravaDesk')}</div>`;let items=publicPosts(page);if(page==='notice')items=notices();if(page==='lost')return heading('Achados e perdidos','Consulte objetos registrados ou envie um relato à administração.')+`<form id="request-form" class="card form-card" data-kind="lost">${input('title','Objeto','text','',true)}${input('body','Descreva o objeto e o local','textarea','',true)}<button class="primary">Registrar objeto</button></form><h2>Meus registros</h2><div class="cards">${requests.filter(r=>r.owner===user.id&&r.kind==='lost').map(r=>requestCard(r,false)).join('')||empty('Nenhum registro.')}</div><h2>Objetos publicados</h2><div class="cards">${items.map(postCard).join('')||empty('Nenhum objeto publicado.')}</div>`;return heading(labels[page]||'Portal',modules.find(m=>m[0]===page)?.[3]||'')+(page==='events'?calendar():'')+`<div class="cards">${items.map(postCard).join('')||empty('Nenhum conteúdo disponível no momento.')}</div>`}
function sidebarSection(name,entries){return `<div class="br-side-section"><div class="br-side-label">${esc(name)}</div>${entries.map(([k,t,i])=>navItem(k,t,i)).join('')}</div>`;}
