 if(!profile?.active){app.innerHTML=`<div class="center"><div class="card card-body">${brand()}<h1>${profile?.registration_status==='rejected'?'Cadastro recusado':'Aguardando liberação'}</h1><p>${profile?.registration_status==='rejected'?'Procure o RH para orientação.':'Seu cadastro precisa ser aprovado pela administração.'}</p>${btn('Verificar novamente','refresh','primary')}${btn('Sair','logout')}</div></div>`;return;}
